export class VoiceEngine {
  constructor() {
    this.recognition = null;
    this.isListening = false;
    this.transcript = '';
    this.silenceTimer = null;
    this.callbacks = { onResult: null, onSilence: null, onError: null };
  }

  setCallbacks(callbacks) { this.callbacks = { ...this.callbacks, ...callbacks }; }

  start() {
    if (!('webkitSpeechRecognition' in window) && !('SpeechRecognition' in window)) {
      if (this.callbacks.onError) this.callbacks.onError('Speech recognition not supported');
      return false;
    }

    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    this.recognition = new SpeechRecognition();
    this.recognition.continuous = true;
    this.recognition.interimResults = true;
    this.recognition.lang = 'en-US';

    this.recognition.onresult = (event) => {
      let interimTranscript = '', finalTranscript = '';
      for (let i = event.resultIndex; i < event.results.length; i++) {
        const text = event.results[i][0].transcript;
        if (event.results[i].isFinal) finalTranscript += text + ' ';
        else interimTranscript += text;
      }
      this.transcript = finalTranscript || interimTranscript;
      if (this.callbacks.onResult) this.callbacks.onResult({ full: this.transcript, interim: interimTranscript, final: finalTranscript });
      this.resetSilenceTimer();
    };

    this.recognition.onerror = (event) => { if (this.callbacks.onError) this.callbacks.onError(event.error); };
    this.recognition.onend = () => { if (this.isListening) this.recognition.start(); };

    try { this.recognition.start(); this.isListening = true; this.resetSilenceTimer(); return true; }
    catch (error) { if (this.callbacks.onError) this.callbacks.onError(error); return false; }
  }

  resetSilenceTimer() {
    if (this.silenceTimer) clearTimeout(this.silenceTimer);
    this.silenceTimer = setTimeout(() => { if (this.callbacks.onSilence && this.isListening) this.callbacks.onSilence(); }, 30000);
  }

  stop() {
    this.isListening = false;
    if (this.silenceTimer) { clearTimeout(this.silenceTimer); this.silenceTimer = null; }
    if (this.recognition) { try { this.recognition.stop(); } catch(e){console.warn(e);} }
    const finalTranscript = this.transcript;
    this.transcript = '';
    return finalTranscript;
  }

  getTranscript() { return this.transcript; }
}
